// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit) public {
        // AdjustBetAmounts is onlyOwner, so we must act as owner
        // The constructor sets owner = msg.sender, which is address(this) in setUp
        // Use vm.prank to call as owner
        vm.prank(address(this));
        c.AdjustBetAmounts(newBetLimit);
        // The reference: currentDifficulty() returns the stored difficulty variable (initially 0)
        // The mutant returns difficulty + 1, so the expected value in reference is 0 (unchanged)
        uint256 diff = c.currentDifficulty();
        // Since difficulty is never set by AdjustBetAmounts, it remains 0
        // In reference, diff == 0; in mutant, diff == 1
        assertTrue(diff == 0);
    }
}

